export function AllInvoicesPage() {
  const [invoices, setInvoices] = useState<AllInvoice[]>([]);
  const [statusFilter, setStatusFilter] = useState('');

  useEffect(() => {
    async function load() {
      const res = await fetch('/api/invoices');
